code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            marks = set()
            while q:
                y,x = q.popleft()
                comp.append((y,x))
                if grid[y][x] not in (0,1):
                    marks.add(grid[y][x])
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not marks:
                continue
            color = min(marks)
            members = set(comp)
            for y,x in comp:
                if all((yy,xx) in members for yy in range(y-1,y+2) for xx in range(x-1,x+2)):
                    out[y][x] = color
            for y,x in comp:
                if grid[y][x] in marks:
                    out[y][x] = grid[y][x]
    return out
'''
